head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getColumnIncrement]<br/>Body Column 정보를 사용하여 특정 Column 의 increment 속성값을 반환합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 increment 속성을 조회할 Body Column 의 인덱스를 설정할 수 있어야 합니다.",
        "columnInfo(필수) 파라미터의 Column 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.",        
        "Body Column 이 inputType='spinner' 인 경우에 동작합니다.",
        "파라미터에 해당하는 Body Column 의 increment 속성값을 반환합니다.",
        "increment 속성이 설정되지 않은 경우 undefined 를 반환합니다.",
        "Column 의 inputType 이 'spinner' 가 아니거나 파라미터에 해당하는 Column 이 없는 경우 false 를 반환합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 : text / spinner Column 을 섞어 구성하고, 인덱스 1(규격)은 숨김 처리한다.
//  - 인덱스 0 : 품목  (text)               -> spinner 아님 -> false
//  - 인덱스 1 : 규격  (text)               -> setColumnVisible(1,false) 로 숨김 (숨김 Column 도 인덱스에 포함) -> spinner 아님 -> false
//  - 인덱스 2 : 수량  (spinner, increment=1)     -> Number 1 (숨김 컬럼 뒤라 인덱스 2)
//  - 인덱스 3 : 단가  (spinner, increment=1000)  -> Number 1000
//  - 인덱스 4 : 비율  (spinner, increment 미설정) -> undefined
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Column 인덱스(숨김 포함) - 0:품목(text) / 1:규격(text, setColumnVisible(1,false) 숨김) / 2:수량(spinner, increment=1) / 3:단가(spinner, increment=1000) / 4:비율(spinner, increment 미설정). 숨긴 규격(인덱스1)도 인덱스에 포함되므로 수량=인덱스2, 단가=인덱스3, 비율=인덱스4.\n[절차] columnInfo(인덱스) 선택 후 (getColumnIncrement 실행) 클릭. 99 는 유효하지 않은 인덱스.\n[확인] spinner+increment 설정(2/3)=설정된 increment 값(Number) / spinner+increment 미설정(4)=undefined / 비 spinner text(0/1)=false / 유효하지않은인덱스(99)=false 가 반환영역에 출력됨."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="cname" name="cname" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cspec" name="cspec" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cqty" name="cqty" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cprice" name="cprice" dataType="text"></w2:column>';
    strDlt += '<w2:column id="crate" name="crate" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    dlt_bind.setJSON([
        { "cname": "노트북", "cspec": "15인치", "cqty": "10", "cprice": "1200000", "crate": "3" },
        { "cname": "모니터", "cspec": "27인치", "cqty": "20", "cprice": "350000", "crate": "5" },
        { "cname": "키보드", "cspec": "무선", "cqty": "30", "cprice": "45000", "crate": "8" }
    ], false);

    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // target 생성 (text / spinner 혼합)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:100%;height:220px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getColumnIncrement 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1"><w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="120" inputType="text" id="h0" value="품목(text)"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="h1" value="규격(숨김)"></w2:column>';
    strTarget += '<w2:column width="130" inputType="text" id="h2" value="수량(spinner,inc=1)"></w2:column>';
    strTarget += '<w2:column width="150" inputType="text" id="h3" value="단가(spinner,inc=1000)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="h4" value="비율(spinner,inc 미설정)"></w2:column>';
    strTarget += '</w2:row></w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1"><w2:row style="" id="brow1">';
    //  (중요) body 컬럼 id 는 dataList 컬럼 id 와 동일해야 셀에 데이터가 바인딩됨
    // 인덱스 0 : 품목 (text) -> spinner 아님 -> false
    strTarget += '<w2:column width="120" inputType="text" id="cname" dataList="cname"></w2:column>';
    // 인덱스 1 : 규격 (text) -> setColumnVisible(1,false) 로 숨김 (숨김 포함 인덱스 검증용) -> false
    strTarget += '<w2:column width="120" inputType="text" id="cspec" dataList="cspec"></w2:column>';
    // 인덱스 2 : 수량 (spinner, increment=1) -> Number 1
    strTarget += '<w2:column width="130" inputType="spinner" id="cqty" dataList="cqty" increment="1"></w2:column>';
    // 인덱스 3 : 단가 (spinner, increment=1000) -> Number 1000
    strTarget += '<w2:column width="150" inputType="spinner" id="cprice" dataList="cprice" increment="1000"></w2:column>';
    // 인덱스 4 : 비율 (spinner, increment 미설정) -> undefined
    strTarget += '<w2:column width="*" inputType="spinner" id="crate" dataList="crate"></w2:column>';
    strTarget += '</w2:row></w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 인덱스 1(규격) 숨김 -> 숨김 Column 도 인덱스에 포함됨을 검증하기 위함
    target1.setColumnVisible(1, false);
}



// getColumnIncrement 조회 (메인 검증 - 인덱스)
//  - spinner + increment 설정 -> 설정된 increment 값(Number)
//  - spinner + increment 미설정 -> undefined
//  - 비 spinner(text) / 없는 인덱스 -> false
scwin.btn_getColumnIncrement_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());

    let colID = target1.getColumnID(columnInfo);
    let inc = target1.getColumnIncrement(columnInfo);

    let result;
    if (typeof inc === 'undefined') {
        result = "undefined (increment 미설정)";
    } else if (inc === false) {
        result = "false (비 spinner 또는 없는 컬럼)";
    } else {
        result = inc + " (typeof " + (typeof inc) + ", 설정된 increment)";
    }

    wf_body_bottom.getObj("scwin").setReturnValue("getColumnIncrement(" + columnInfo + ") [getColumnID:" + colID + "] -> " + result);
}
